using System.Text.Json;
using Forge.Network.Authoring;
using Forge.Network.Operations;
using Forge.Network.Sessions;
namespace Forge.LiveDirector.Authoring;

public sealed record LiveDirectorNarrativeProfile(Guid Id, int SchemaVersion, string Provenance, NetworkAuthorityScope AuthorityScope, long ServerRevision, string AuditIdentity, bool RequiredAtRuntime,
 bool QuestInspection, IReadOnlyList<string> QuestScopes, bool ConsequencePreview, bool QuestRuntimeAdapter,
 IReadOnlyList<string> EncounterActions, bool BoundedScaling, bool CreatureSpawnAdapter, bool AiRuntimeAdapter)
{ public static LiveDirectorNarrativeProfile CreateDefault(string provenance = "openrpg:r130") => new(Guid.Parse("d1300000-0000-4000-8000-000000000001"), 1, provenance, NetworkAuthorityScope.Server, 0, "live.director", false, true, ["all-players", "selected-players"], true, true, ["activate", "pause", "wave", "scale", "despawn"], true, true, true); }
public static class LiveDirectorNarrativeValidator { public static IReadOnlyList<NetworkDiagnostic> Validate(LiveDirectorNarrativeProfile p) { var d = new List<NetworkDiagnostic>(); if (p.Id == Guid.Empty) A("LIVE_NARRATIVE_UUID_INVALID", "/liveDirector/narrative", p.Id, d); if (p.SchemaVersion != 1) A("LIVE_NARRATIVE_SCHEMA_UNSUPPORTED", "/liveDirector/narrative/schemaVersion", p.Id, d); if (string.IsNullOrWhiteSpace(p.Provenance) || p.AuthorityScope != NetworkAuthorityScope.Server || p.ServerRevision < 0 || string.IsNullOrWhiteSpace(p.AuditIdentity)) A("LIVE_NARRATIVE_IDENTITY_INVALID", "/liveDirector/narrative/identity", p.Id, d); if (!p.QuestInspection || p.QuestScopes.Count != 2 || !p.ConsequencePreview || !p.QuestRuntimeAdapter) A("LIVE_QUEST_POLICY_INVALID", "/liveDirector/narrative/quests", p.Id, d); if (p.EncounterActions.Count != 5 || !p.BoundedScaling || !p.CreatureSpawnAdapter || !p.AiRuntimeAdapter) A("LIVE_ENCOUNTER_POLICY_INVALID", "/liveDirector/narrative/encounters", p.Id, d); return d; } private static void A(string c, string path, Guid id, ICollection<NetworkDiagnostic> d) => d.Add(new(c, path, "Required narrative capability missing.", id)); }
public sealed record LiveDirectorNarrativeCommand(Guid CommandId, int SchemaVersion, string Provenance, long ExpectedRevision, string ActorId, NetworkRole Role, bool Apply, LiveDirectorNarrativeProfile Candidate); public sealed record LiveDirectorNarrativeResult(bool Succeeded, bool Applied, LiveDirectorNarrativeProfile Profile, IReadOnlyList<NetworkDiagnostic> Diagnostics, string SemanticDiff, string AuditEntry);
public sealed class LiveDirectorNarrativeHistory { private readonly Stack<LiveDirectorNarrativeProfile> u = []; private readonly Stack<LiveDirectorNarrativeProfile> r = []; public LiveDirectorNarrativeHistory(LiveDirectorNarrativeProfile p) { if (LiveDirectorNarrativeValidator.Validate(p).Count != 0) throw new ArgumentException("LIVE_NARRATIVE_INITIAL_INVALID"); Current = p; } public LiveDirectorNarrativeProfile Current { get; private set; } public LiveDirectorNarrativeResult Execute(LiveDirectorNarrativeCommand c) { var d = LiveDirectorNarrativeValidator.Validate(c.Candidate).ToList(); if (c.CommandId == Guid.Empty || c.SchemaVersion != 1 || string.IsNullOrWhiteSpace(c.Provenance)) d.Add(new("LIVE_NARRATIVE_COMMAND_INVALID", "/liveDirector/narrative/command", "Identity required.", c.CommandId)); if (string.IsNullOrWhiteSpace(c.ActorId) || c.Role is not (NetworkRole.GameMaster or NetworkRole.Administrator)) d.Add(new("LIVE_NARRATIVE_PERMISSION_DENIED", "/liveDirector/narrative/audit/actor", "GM required.", c.Candidate.Id)); if (c.ExpectedRevision != Current.ServerRevision || c.Candidate.ServerRevision != Current.ServerRevision + 1) d.Add(new("LIVE_NARRATIVE_REVISION_STALE", "/liveDirector/narrative/serverRevision", "Revision stale.", c.Candidate.Id)); const string diff = "quests,encounters"; if (d.Count != 0) return X(false, false, Current, d, diff, "rejected", c.ActorId); if (!c.Apply) return X(true, false, Current, [], diff, "previewed", c.ActorId); u.Push(Current); Current = c.Candidate; r.Clear(); return X(true, true, Current, [], diff, "applied", c.ActorId); } public LiveDirectorNarrativeResult Undo(string a, NetworkRole role) => M(u, r, a, role, "undo"); public LiveDirectorNarrativeResult Redo(string a, NetworkRole role) => M(r, u, a, role, "redo"); private LiveDirectorNarrativeResult M(Stack<LiveDirectorNarrativeProfile> f, Stack<LiveDirectorNarrativeProfile> t, string a, NetworkRole role, string action) { if (f.Count == 0 || role is not (NetworkRole.GameMaster or NetworkRole.Administrator)) return X(false, false, Current, [new("LIVE_NARRATIVE_HISTORY_DENIED", "/liveDirector/narrative/history", "Unavailable.", Current.Id)], "none", "rejected", a); t.Push(Current); Current = f.Pop(); return X(true, true, Current, [], "narrative", $"compensated:{action}", a); } private static LiveDirectorNarrativeResult X(bool ok, bool ap, LiveDirectorNarrativeProfile p, IReadOnlyList<NetworkDiagnostic> d, string diff, string action, string actor) => new(ok, ap, p, d, diff, $"{action}:live.narrative:actor={actor}:revision={p.ServerRevision}"); }
public sealed class LiveDirectorNarrativeStore { private static readonly JsonSerializerOptions O = new() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase, WriteIndented = true }; public string Serialize(LiveDirectorNarrativeProfile p) { var d = LiveDirectorNarrativeValidator.Validate(p); if (d.Count != 0) throw new InvalidDataException(d[0].Code); return JsonSerializer.Serialize(p, O).Replace("\r\n", "\n", StringComparison.Ordinal) + "\n"; } public LiveDirectorNarrativeProfile Deserialize(string j) { var p = JsonSerializer.Deserialize<LiveDirectorNarrativeProfile>(j, O) ?? throw new InvalidDataException("LIVE_NARRATIVE_EMPTY"); var d = LiveDirectorNarrativeValidator.Validate(p); if (d.Count != 0) throw new InvalidDataException(d[0].Code); return p; } }
public sealed record LiveDirectorNarrativeResolution(bool Available, LiveDirectorNarrativeProfile? Profile, IReadOnlyList<NetworkDiagnostic> Diagnostics); public static class LiveDirectorNarrativeRuntimeAdapter { public static LiveDirectorNarrativeResolution Resolve(LiveDirectorNarrativeProfile? p, bool req) { if (p is null) return req ? new(false, null, [new("LIVE_NARRATIVE_REQUIRED_MISSING", "/liveDirector/narrative", "Required profile missing.")]) : new(false, null, []); var d = LiveDirectorNarrativeValidator.Validate(p); return new(d.Count == 0, d.Count == 0 ? p : null, d); } }
public readonly record struct LiveDirectorNarrativeHandle(Guid ProfileId, int Generation); public sealed record LiveDirectorNarrativeSnapshot(Guid Id, long Revision, int QuestScopes, int EncounterActions, bool SpawnAdapter, bool AiAdapter); public sealed class LiveDirectorNarrativeScriptService(LiveDirectorNarrativeProfile p) { public LiveDirectorNarrativeHandle Handle { get; } = new(p.Id, 1); public LiveDirectorNarrativeSnapshot Read(LiveDirectorNarrativeHandle h) { if (h.ProfileId != p.Id || h.Generation != 1) throw new InvalidOperationException("LIVE_NARRATIVE_HANDLE_INVALID"); return new(p.Id, p.ServerRevision, p.QuestScopes.Count, p.EncounterActions.Count, p.CreatureSpawnAdapter, p.AiRuntimeAdapter); } }
